  "synopsis": "广播站突发断电，周野怀疑维修员林岚故意破坏。林岚用专业检测排除人为剪线，查明外墙电源接头进水，并指出根本原因是防水胶圈老化。误会解除后两人合作修复，却在通电时遭遇未知的倒计时电子音。",
  "preview_blurb": "老街广播站突发断电，主持人周野与维修员林岚在排查故障时互相猜疑。当老化的胶圈揭开断电真相，两人刚建立信任，调音台却传出了诡异的倒计时声。",
  "scenes": [
    {
      "title": "突发断电与猜疑",
      "location": "广播站室内",
      "dramatic_goal": "确立断电危机，展现周野的防备与林岚的专业冷静。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "怎么黑了？推子怎么没反应？林岚，你是不是拔错线了？街道派你来拆广播站是不是？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别碰调音台。有焦味。退后。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "你别转移话题，线是不是你剪的？街坊还等着听天气预报呢，这节骨眼断电，怎么交代？"
        },
        {
          "kind": "narration",
          "text": "窗外雨声骤大，屋内只剩应急灯的微光。"
        }
      ]
    },
    {
      "title": "排查外墙与解除误会",
      "location": "广播站外墙",
      "dramatic_goal": "通过检测推翻人为破坏猜想，查明胶圈老化真相，化解信息差。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "看这里。万用表读数归零，线没断，是电源端短路。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "那外墙接头呢？昨晚我用水管冲过外墙，是不是进水了？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "拆开看看。拿手电。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "全是泥水。看这圈橡胶，硬化开裂了。根本原因是防水胶圈老化，不是你弄坏的。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "真不是我的锅？哎哟，我这防备心算是喂了狗了。对不住啊，林师傅，我错怪你了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "不用道歉。把工具包递给我。拿干毛巾。把积水擦干，我换新胶圈。"
        }
      ]
    },
    {
      "title": "合作修复与未知倒计时",
      "location": "广播站室内",
      "dramatic_goal": "完成修复并约定敲铃，但在通电瞬间引入新的悬念危机。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "擦干了。等会儿通了电，我敲三声铃给街坊报平安，也算给你这趟维修接风了。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "胶圈换好了。进去推闸。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "亮了亮了！我这就去敲铃！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "别动。这声音不是广播站的。"
